import{_ as a,o as r,c as o,l as n,t as i,N as t}from"./chunks/framework.CMqbtke2.js";const u=JSON.parse('{"title":"proc_profile | x-cmd man (man5) | kernel profiling","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | proc_profile - kernel profiling","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"proc_profile | x-cmd man (man5) | kernel profiling"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | proc_profile - kernel profiling"}]]},"headers":[],"params":{"isMan":true,"man":"proc_profile","category":"man5","desc":"kernel profiling"},"relativePath":"man5/proc_profile.md","filePath":"man5/proc_profile.md"}'),l={name:"man5/proc_profile.md"},s={class:"visually-hidden"},p=t('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>/proc/profile - kernel profiling</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><dl><dt><em>/proc/profile</em> (since Linux 2.4)</dt><dd>This file is present only if the kernel was booted with the <em>profile=1</em> command-line option. It exposes kernel profiling information in a binary format for use by <strong>readprofile</strong>(1). Writing (e.g., an empty string) to this file resets the profiling counters; on some architectures, writing a binary integer &quot;profiling multiplier&quot; of size <em>sizeof(int)</em> sets the profiling interrupt frequency.</dd></dl><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>proc</strong>(5)</p>',6);function c(e,m,d,f,_,h){return r(),o("div",null,[n("h1",s,i(e.$params.man),1),p])}const k=a(l,[["render",c]]);export{u as __pageData,k as default};
